/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to prices and add entry to Price Change tracking table for later processing
/// </summary>
public class METPriceChangeTrackManage
{
}

Method.Source:
    /// <summary>
    /// MPJ_24248 Pricing Data Extract
    /// Process the change 
    /// </summary>
    /// <param name = "_parameters">Container of Parameters</param>
    public static container trackChange(container _parameters)
    {
        container   resultCon;

        try
        {
            METPriceChangeType  priceChangeType = conPeek(_parameters, 1);
            Common              common          = conPeek(_parameters, 2);

            METPriceChangeTrack priceChangeTrack = METPriceChangeTrackFactory::newFromPriceChangeType(priceChangeType);
            priceChangeTrack.initInstanceSource(common);
            priceChangeTrack.processSource();
        }
        catch
        {
            int line = infologLine();
            for(int i = 1; i <= line ; i++)
            {
                str message = infolog.text(i);

                resultCon += [message];
            }
        }

        return  resultCon;
    }

    /// <summary>
    /// Result of the trackChange operation
    /// </summary>
    /// <param name = "_result">Result</param>
    public static void callBackResult(AsyncTaskResult _result)
    {
        container result;
        str resultstr;
        ;
 
        result      = _result.getResult();
        resultstr   = conPeek(result, 1);
 
        if(resultstr)
        {
            SystemNotificationDataContract notification = new SystemNotificationDataContract();
            notification.Users().value(1, curUserId());
            notification.Title("@MET:PriceChangeTracking");
            notification.RuleId('PriceChangeTracking');
            notification.Message(resultstr);
            notification.Severity(SystemNotificationSeverity::Error);
            notification.ExpirationDateTime(DateTimeUtil::addHours(DateTimeUtil::utcNow(), 24));

            SystemNotificationsManager::AddSystemNotification(notification);
        }
    }
